(x, y, t) => {
  const w1 = Math.sin(x*0.008+t*0.2)*Math.cos(y*0.006-t*0.15)*30;
  const w2 = Math.cos(x*0.012-t*0.18)*Math.sin(y*0.01+t*0.22)*20;
  const w3 = Math.sin((x+y)*0.007+t*0.1)*Math.cos((x-y)*0.009-t*0.12)*15;
  const wx = x+w1+w2, wy = y+w1*0.5+w3;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.8],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.2],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.9],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.1],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.7],
    [80+Math.sin(t*0.7+3)*60,40+Math.cos(t*0.5+2)*40,0.14,1.3,0.6],
    [400+Math.cos(t*0.45+1)*70,200+Math.sin(t*0.65+4)*50,0.11,2.1,0.85]
  ];
  let aS=0,iS=0,a2=0,i2=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((wx-sX)**2+(wy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    a2+=Math.sin(d*f*1.618-t*sp*0.8+0.5)*w*0.5;
    i2+=Math.cos(d*f*0.433+t*sp*0.4-0.8)*w*0.4;
  }
  const n=src.length;
  const act=(aS+a2)/(n*1.5),inh=(iS+i2)/(n*1.4);
  const bg=(Math.sin(wx*0.04+wy*0.025+t*0.8)+Math.sin(wx*0.03-wy*0.04+t*1.1))/2+Math.sin((wx+wy)*0.12+t*2.5)*0.2+Math.sin((wx-wy)*0.1-t*2)*0.2;
  const cx=240,cy=120,dist=Math.sqrt((wx-cx)**2+(wy-cy)**2),ang=Math.atan2(wy-cy,wx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const golden=Math.sin(dist*0.031-ang*5-t*0.8)*0.25;
  const cX=wx*0.15,cY=wy*0.15;
  const cell=Math.sin(cX)*Math.sin(cY)+Math.sin((cX+cY)*0.7+t)*0.5;
  const cell2=Math.sin(cX*1.3+t*0.5)*Math.cos(cY*1.1-t*0.3);
  const cellB=Math.tanh(cell*1.5)*0.3+Math.tanh(cell2*1.2)*0.2;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+golden)*2.2);
  const diffusion=Math.tanh((act*0.3+inh*0.5-bg*0.2)*1.5)*0.3;
  const blend=reaction*0.7+cellB+diffusion,v=blend*0.5+0.5;
  const pal=[[5,10,48],[8,35,72],[12,72,98],[22,120,125],[65,165,135],[155,195,120],[215,200,95],[230,170,90],[220,120,85],[190,72,88],[140,40,82],[75,20,68],[30,12,52],[5,10,48]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(reaction)>0.65?1.18:1.0;
  const vig=Math.max(0.55,1.0-dist*0.0005);
  const hi=Math.abs(reaction)>0.85?Math.pow(Math.abs(reaction),3)*40:0;
  const s=lum*edge*vig;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*s+hi)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*s+hi*0.8)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*s+hi*0.6)|0
  ];
}
